package zones

import (
	_ "embed"
	"encoding/json"
	"math"
	"strings"
	"sync"
)

// § 5 KCanG is German law, so zones exist only in Germany: tiles outside it
// are never fetched, and places outside it are dropped from border tiles.
//
// germany_border.txt holds Germany's border (OSM relation 51477, outer rings
// only, simplified to 20 m) as encoded polylines, one ring per line. It is
// generated by backend/cmd/germanyborder, which also writes the same rings
// for the app (app/lib/features/zones/germany_border.g.dart).
//
//go:embed germany_border.txt
var germanyBorderData string

// bandDeg is the height of the latitude bands that index the border edges.
const bandDeg = 0.02

type edge struct{ a, b pt }

type border struct {
	s, w, n, e float64 // bounding box
	bands      [][]edge
}

// Overlap is how a box relates to Germany.
type Overlap int

const (
	Outside Overlap = iota // no part of the box is in Germany
	Inside                 // all of it is
	Partly                 // the border runs through it
)

var germany = sync.OnceValue(func() *border { return newBorder(GermanyRings()) })

// GermanyRings decodes the embedded border rings ([lat, lon] points).
func GermanyRings() [][]pt {
	var rings [][]pt
	for _, line := range strings.Split(germanyBorderData, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		rings = append(rings, DecodePolyline(line))
	}
	return rings
}

func newBorder(rings [][]pt) *border {
	b := &border{s: math.Inf(1), w: math.Inf(1), n: math.Inf(-1), e: math.Inf(-1)}
	for _, r := range rings {
		for _, p := range r {
			b.s, b.n = math.Min(b.s, p[0]), math.Max(b.n, p[0])
			b.w, b.e = math.Min(b.w, p[1]), math.Max(b.e, p[1])
		}
	}
	b.bands = make([][]edge, b.band(b.n)+1)
	for _, r := range rings {
		for i := range r {
			e := edge{r[i], r[(i+1)%len(r)]}
			lo, hi := b.band(math.Min(e.a[0], e.b[0])), b.band(math.Max(e.a[0], e.b[0]))
			for k := lo; k <= hi; k++ {
				b.bands[k] = append(b.bands[k], e)
			}
		}
	}
	return b
}

// band is the index of the latitude band holding lat, clamped to the index.
func (b *border) band(lat float64) int {
	k := int(math.Floor((lat - b.s) / bandDeg))
	if k < 0 {
		return 0
	}
	if b.bands != nil && k >= len(b.bands) {
		return len(b.bands) - 1
	}
	return k
}

// contains is an even-odd ray cast to the east over the edges in lat's band.
func (b *border) contains(lat, lon float64) bool {
	if lat < b.s || lat > b.n || lon < b.w || lon > b.e {
		return false
	}
	in := false
	for _, e := range b.bands[b.band(lat)] {
		if (e.a[0] > lat) != (e.b[0] > lat) {
			x := e.a[1] + (lat-e.a[0])*(e.b[1]-e.a[1])/(e.b[0]-e.a[0])
			if lon < x {
				in = !in
			}
		}
	}
	return in
}

// overlap classifies the box s, w, n, e.
func (b *border) overlap(s, w, n, e float64) Overlap {
	if n < b.s || s > b.n || e < b.w || w > b.e {
		return Outside
	}
	for k := b.band(s); k <= b.band(n); k++ {
		for _, ed := range b.bands[k] {
			if segmentHitsBox(ed.a, ed.b, s, w, n, e) {
				return Partly
			}
		}
	}
	// no edge inside the box: it is wholly in or wholly out
	if b.contains((s+n)/2, (w+e)/2) {
		return Inside
	}
	return Outside
}

// segmentHitsBox: Liang-Barsky clipping of segment a-b against the box.
func segmentHitsBox(a, b pt, s, w, n, e float64) bool {
	t0, t1 := 0.0, 1.0
	dLat, dLon := b[0]-a[0], b[1]-a[1]
	for _, c := range [4][2]float64{
		{-dLon, a[1] - w}, {dLon, e - a[1]},
		{-dLat, a[0] - s}, {dLat, n - a[0]},
	} {
		p, q := c[0], c[1]
		if p == 0 {
			if q < 0 {
				return false
			}
			continue
		}
		r := q / p
		if p < 0 {
			t0 = math.Max(t0, r)
		} else {
			t1 = math.Min(t1, r)
		}
		if t0 > t1 {
			return false
		}
	}
	return true
}

// InGermany reports whether lat/lon lies in Germany.
func InGermany(lat, lon float64) bool { return germany().contains(lat, lon) }

// GermanyOverlap classifies a box (degrees) against Germany.
func GermanyOverlap(s, w, n, e float64) Overlap { return germany().overlap(s, w, n, e) }

// DecodePolyline decodes Google's encoded polyline format (precision 1e-5)
// into [lat, lon] points.
func DecodePolyline(s string) []pt {
	var out []pt
	var lat, lon int
	i := 0
	next := func() int {
		v, shift := 0, 0
		for i < len(s) {
			c := int(s[i]) - 63
			i++
			v |= (c & 0x1f) << shift
			shift += 5
			if c < 0x20 {
				break
			}
		}
		if v&1 != 0 {
			return ^(v >> 1)
		}
		return v >> 1
	}
	for i < len(s) {
		lat += next()
		lon += next()
		out = append(out, pt{float64(lat) / 1e5, float64(lon) / 1e5})
	}
	return out
}

// EncodePolyline is the inverse of DecodePolyline.
func EncodePolyline(points []pt) string {
	var sb strings.Builder
	put := func(v int) {
		u := v << 1
		if v < 0 {
			u = ^u
		}
		for u >= 0x20 {
			sb.WriteByte(byte((0x20 | (u & 0x1f)) + 63))
			u >>= 5
		}
		sb.WriteByte(byte(u + 63))
	}
	var pLat, pLon int
	for _, p := range points {
		lat, lon := int(math.Round(p[0]*1e5)), int(math.Round(p[1]*1e5))
		put(lat - pLat)
		put(lon - pLon)
		pLat, pLon = lat, lon
	}
	return sb.String()
}

// zoneInGermany reports whether any point of the zone's geometry lies in
// Germany (a site across the border counts).
func zoneInGermany(z Zone) bool {
	var c any
	if err := json.Unmarshal(z.Geometry.Coordinates, &c); err != nil {
		return false
	}
	var walk func(v any) bool
	walk = func(v any) bool {
		l, ok := v.([]any)
		if !ok {
			return false
		}
		if len(l) == 2 {
			lat, ok1 := l[0].(float64)
			lon, ok2 := l[1].(float64)
			if ok1 && ok2 {
				return InGermany(lat, lon)
			}
		}
		for _, x := range l {
			if walk(x) {
				return true
			}
		}
		return false
	}
	return walk(c)
}
